from __future__ import annotations


def merge_profile(record, profile):
    merged = dict(record)
    # Null request values are missing values too, so they must be eligible for
    # profile enrichment.  A null profile value remains null for the fallback
    # policy to resolve.
    for field_name in ("timezone", "currency"):
        if merged.get(field_name) is None:
            merged[field_name] = profile.get(field_name)
    return merged

