import json
from pathlib import Path

from fallback_policy import fill_system_defaults
from mock_profile_api import TRACE as PROFILE_TRACE, get_profile
from mock_transaction_api import TRACE as TX_TRACE, send_transaction
from normalization_policy import normalize_currency
from profile_merge import merge_profile
from transaction_contract import REQUIRED_FIELDS


def validate_record(record):
    if not isinstance(record, dict):
        return list(REQUIRED_FIELDS)

    # These are the fields the caller must provide.  Currency and timezone are
    # deliberately not required here: both can be supplied by the profile
    # service or by the system defaults.
    missing = [
        field_name
        for field_name in REQUIRED_FIELDS
        if field_name not in record or record[field_name] is None
    ]
    return missing


def enrich(record):
    try:
        profile = get_profile(record["user_id"])
    except KeyError:
        # A profile miss is an expected enrichment outcome, not a transaction
        # failure.  The fallback policy supplies the missing values below.
        profile = {}
    merged = merge_profile(record, profile)
    return fill_system_defaults(merged)


def normalize(record):
    return normalize_currency(record)


def process_transactions(path):
    PROFILE_TRACE.clear()
    TX_TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    # Validate the complete batch before touching either external service.
    # This also prevents a later invalid record from causing a partially sent
    # batch.
    validation_errors = {
        index: missing
        for index, record in enumerate(payload)
        if (missing := validate_record(record))
    }
    if validation_errors:
        details = "; ".join(
            f"record {index}: missing {', '.join(fields)}"
            for index, fields in validation_errors.items()
        )
        raise ValueError(f"invalid transaction request(s): {details}")

    results = []
    for record in payload:
        enriched = enrich(record)
        normalized = normalize(enriched)
        results.append(send_transaction(normalized))
    return {"results": results, "profile_trace": list(PROFILE_TRACE), "tx_trace": list(TX_TRACE)}
